import json
import re
from pathlib import Path
from typing import Any

from mindustry_port.java_ast import parse_source_tree


def gdscript_literal(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, sort_keys=True)


def _script_path(java_file: dict, type_entry: dict) -> Path:
    package_path = java_file.get("package", "").replace(".", "/")
    return Path(package_path) / f"{type_entry['name']}.gd"


def _gd_identifier(value: str) -> str:
    identifier = re.sub(r"[^A-Za-z0-9_]", "_", value)
    identifier = re.sub(r"_+", "_", identifier).strip("_")
    if not identifier:
        return "unnamed"
    if identifier[0].isdigit():
        return f"_{identifier}"
    return identifier


def _gdscript_preload_alias(class_name: str) -> str:
    return _gd_identifier(re.sub(r"([a-z0-9])([A-Z])", r"\1_\2", class_name).lower())


def _canonicalize_generated_preload_aliases(lines: list[str]) -> list[str]:
    preload_pattern = re.compile(
        r"^(?P<indent>\s*const\s+)(?P<alias>[A-Za-z_][A-Za-z0-9_]*)"
        r"(?P<assignment>\s*:=\s*preload\(\"[^\"]+/)"
        r"(?P<class_name>[A-Za-z_][A-Za-z0-9_]*)"
        r"(?P<suffix>\.gd\"\)\s*)$"
    )
    renames: dict[str, str] = {}
    for line in lines:
        match = preload_pattern.match(line)
        if match and match.group("alias") == match.group("class_name"):
            renames[match.group("alias")] = _gdscript_preload_alias(match.group("class_name"))

    canonicalized: list[str] = []
    for line in lines:
        for class_name, alias in renames.items():
            line = line.replace(f"const {class_name} := preload(", f"const {alias} := preload(", 1)
            line = re.sub(rf"(?<!/)\b{re.escape(class_name)}\.", f"{alias}.", line)
        canonicalized.append(line)
    return canonicalized


